/* Exact descriptive-statistics states. Fixed axes, original identities, explicit contracts. */
(() => {
'use strict';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cp=x=>JSON.parse(JSON.stringify(x));
const fmt=x=>x===null?'undefined':Number.isInteger(x)?String(x):Number(x.toFixed(5)).toString();
const sum=a=>a.reduce((s,x)=>s+x,0);
function summary(a){const mean=sum(a)/a.length,m2=sum(a.map(x=>(x-mean)**2));return {n:a.length,mean,m2,v:m2/a.length,s2:a.length>1?m2/(a.length-1):null};}
function quant(a,p,type='type7'){const s=[...a].sort((a,b)=>a-b);if(type==='nearest')return s[Math.max(0,Math.ceil(s.length*p)-1)];const h=(s.length-1)*p,j=Math.floor(h);return s[j]+(h-j)*((s[j+1]??s[j])-s[j]);}
const math=s=>'<math xmlns="http://www.w3.org/1998/Math/MathML"><mrow>'+s.split(/([=+−×÷≤≥<>(),;])/).filter(Boolean).map(t=>/^[=+−×÷≤≥<>(),;]$/.test(t)?'<mo>'+esc(t)+'</mo>':/^\s*-?\d+(\.\d+)?\s*$/.test(t)?'<mn>'+t.trim()+'</mn>':'<mtext>'+esc(t)+'</mtext>').join('')+'</mrow></math>';
const text=(x,y,s,cls='label',anchor='start')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" class="stat-${cls}">${esc(s)}</text>`;
const line=(x,y,u,v,color='#8095a3',dash='')=>`<line x1="${x}" y1="${y}" x2="${u}" y2="${v}" stroke="${color}" stroke-width="2" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;
const wrap=(s,h=420)=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 ${h}" role="img" data-visual-type="plot">${s.replace(/<rect x="([^"]+)" y="([^"]+)" width="([^"]+)" height="([^"]+)"([^>]*)\/>/g,(_,a,b,c,d,attrs)=>{const x=+a,y=+b,w=+c,h=+d;return `<polygon points="${x},${y} ${x+w},${y} ${x+w},${y+h} ${x},${y+h}"${attrs}/>`;})}</svg>`;
const range=a=>{let lo=Math.min(...a),hi=Math.max(...a),pad=Math.max(1,(hi-lo)*.12);return [lo-pad,hi+pad];};
const mapper=(r,a,b)=>x=>a+(x-r[0])/(r[1]-r[0])*(b-a);
function axis(r,y=310,label='Value'){let s=line(90,y,910,y);const x=mapper(r,90,910);for(let j=0;j<=5;j++){const v=r[0]+j*(r[1]-r[0])/5;s+=line(x(v),y,x(v),y+6)+text(x(v),y+28,fmt(v),'math','middle');}return s+text(500,y+57,label,'label','middle');}
function vertical(r,label){const y=mapper(r,320,80);let s=line(90,80,90,320)+text(35,60,label);for(let j=0;j<=4;j++){const v=r[0]+j*(r[1]-r[0])/4;s+=line(84,y(v),90,y(v))+text(74,y(v)+5,fmt(v),'math','end');}return s;}
function dot(x,y,id,label,color='#497d99'){return `<g data-entity="${esc(id)}"><circle cx="${x}" cy="${y}" r="7" fill="${color}"/>${label!==null?text(x,y-18,label,'math','middle'):''}</g>`;}
const diff=(a,b,p='')=>JSON.stringify(a)===JSON.stringify(b)?[]:a&&b&&typeof a==='object'&&typeof b==='object'?[...new Set([...Object.keys(a),...Object.keys(b)])].flatMap(k=>diff(a[k],b[k],p?p+'.'+k:k)):[{field:p,before:a??null,after:b??null}];
function make(id,title,kind,invariant,guide){return {id,title,kind,invariant,code:guide,frames:[]};}
function frame(m,state,svg,operation,why,checks=[],formula='',active=0){const snapshot=cp(state),prev=m.frames.at(-1)?.snapshot;m.frames.push({snapshot,svg,caption:why,formulaHtml:formula?math(formula):'',teaching:{operation,why,checks:checks.map(([s,r])=>({mathHtml:math(s),result:String(r)})),changes:prev?diff(prev,snapshot):[],currentState:snapshot,initial:!prev,reading:m.invariant,guide:m.code,activeLine:active,mode:m.kind}});}

function histogram(a,edges,id='histogram'){
 const m=make(id,'Density histogram: assign records, then recover mass by area','histogram-density','The horizontal axis retains actual bin widths. Counts and density heights are different quantities. Bins are [left,right), with the last right endpoint included.',['Start with zero counts.','Locate one record using both endpoint tests.','Increase only its bin count.','Divide each count by sample size and actual width.','Check that the areas sum to one.']);
 const counts=Array(edges.length-1).fill(0),maxHeight=Math.max(...counts.map((_,j)=>1/(edges[j+1]-edges[j]))),x=mapper([edges[0],edges.at(-1)],90,910),scale=230/maxHeight;
 const draw=(seen,active=null)=>{let s=text(40,32,'Observed records: '+seen+'/'+a.length+'; heights use the fixed final sample size '+a.length)+line(90,330,910,330)+text(500,387,'Measured value','label','middle')+edges.map(v=>line(x(v),330,x(v),336)+text(x(v),358,fmt(v),'math','middle')).join('')+line(90,100,90,330)+[0,.25,.5,.75,1].map(f=>text(74,335-f*230,fmt(f*maxHeight),'math','end')).join('')+text(32,60,'Density');for(let j=0;j<counts.length;j++){const h=counts[j]/(a.length*(edges[j+1]-edges[j])),left=x(edges[j]),right=x(edges[j+1]),yp=330-h*scale;s+=`<rect x="${left}" y="${yp}" width="${right-left}" height="${h*scale}" fill="${j===active?'#e5c58e':'#b7d8d1'}" stroke="#628b89"/>`+text((left+right)/2,83,'count '+counts[j],'math','middle')+text((left+right)/2,108,'height '+fmt(h),'math','middle');}s+=text(40,420,'Bar top coordinates use one fixed density scale throughout this trace.');return wrap(s,455);};
 frame(m,{values:a,edges,counts,seen:0},draw(0),'Initialize bins','No record has been assigned; density areas are not normalized until all records are counted.');
 a.forEach((v,i)=>{const j=counts.findIndex((_,j)=>v>=edges[j]&&(v<edges[j+1]||(j===counts.length-1&&v<=edges[j+1])));if(j<0)throw Error('Every observation must lie within the supplied outer edges.');frame(m,{values:a,edges,counts,seen:i,value:v,bin:j},draw(i,j),'Test bin membership','Test the actual left and right endpoints; the final bin alone retains its right endpoint.',[[`${v} ≥ ${edges[j]}`,true],[`${v} ${j===counts.length-1?'≤':'<'} ${edges[j+1]}`,true]],'',1);counts[j]++;frame(m,{values:a,edges,counts,seen:i+1,bin:j},draw(i+1,j),'Add one record','Only this bin count increases. Its height rises by one divided by final sample size and bin width.',[],`bin ${j+1} count = ${counts[j]}`,2);});
 m.result={counts:cp(counts),heights:counts.map((f,j)=>f/(a.length*(edges[j+1]-edges[j]))),area:sum(counts)/a.length};frame(m,{...m.result,edges,values:a},draw(a.length),'Normalize the complete histogram','Every record appears exactly once. Multiplying each density height by its width recovers the corresponding relative frequency.',[['sum of bin areas = 1',m.result.area===1]],'total area = 1',4);return m;
}

function ecdf(a,id='ecdf'){
 const m=make(id,'Empirical CDF: tied jumps and endpoint mass','empirical-step-function','Each value location has one right-continuous jump containing all its tied records. A closed dot marks the value at the threshold; an open dot marks its excluded left limit.',['Sort distinct values and preserve multiplicities.','Count all records equal to the next value.','Draw a jump of multiplicity / n.','Compare the left limit and the included value.']);const keys=[...new Set(a)].sort((a,b)=>a-b),r=range(a),x=mapper(r,90,910),y=v=>320-230*v;let rows=[],count=0;
 const draw=()=>{let s=axis(r,320,'Threshold t')+line(90,90,90,320)+text(45,95,'1','math')+text(45,325,'0','math')+text(40,30,'F(t) is the fraction at or below t');let prev=r[0],lev=0;for(const row of rows){s+=line(x(prev),y(lev),x(row.value),y(lev),'#407f91')+line(x(row.value),y(lev),x(row.value),y(row.after),'#407f91','4 4')+`<circle cx="${x(row.value)}" cy="${y(lev)}" r="5" fill="white" stroke="#407f91" stroke-width="2"/>`+dot(x(row.value),y(row.after),'jump-'+row.value,null);prev=row.value;lev=row.after;}s+=line(x(prev),y(lev),x(r[1]),y(lev),'#407f91');if(rows.length){const row=rows.at(-1);s+=text(190,420,`At ${row.value}: left limit ${fmt(row.before)}, included value ${fmt(row.after)}, jump ${fmt(row.mass)}`,'math');}return wrap(s,455);};
 frame(m,{values:a,rows,count},draw(),'Start before the minimum','The complete ECDF is zero below its first observed value; later jumps are not yet drawn.');for(const v of keys){const k=a.filter(x=>x===v).length,before=count/a.length;count+=k;rows.push({value:v,before,after:count/a.length,mass:k/a.length,multiplicity:k});frame(m,{values:a,rows,count,value:v},draw(),'Add a complete tie jump','All records equal to this value enter together. The left limit excludes them and the threshold value includes them.',[[`count equal to ${v} = ${k}`,true]],`jump = ${k} ÷ ${a.length}`,1);}m.result=rows;return m;
}

function center(a,id='mean',absolute=false){
 const mean=summary(a).mean,lo=quant(a,.5,'nearest'),sorted=[...a].sort((a,b)=>a-b),hi=sorted[Math.floor(a.length/2)],r=range([...a,mean]),x=mapper(r,90,910),loss=c=>sum(a.map(v=>absolute?Math.abs(v-c):(v-c)**2)),centers=[r[0],sorted[0],lo,(lo+hi)/2,mean,hi,sorted.at(-1),r[1]],maxLoss=Math.max(loss(r[0]),loss(r[1])),y=z=>320-240*z/maxLoss;
 const m=make(id,absolute?'Absolute loss: a flat median interval':'Squared loss: the unique mean minimum',absolute?'absolute-loss':'squared-loss',absolute?'The full loss curve is fixed. The center marker moves; the minimizing interval lies between the two middle records.':'The quadratic curve and value axis are fixed. Moving the proposed center raises loss by n times its squared distance from the mean.',['Choose a proposed center.','Compute every residual contribution at that center.','Add the contributions.','Compare with the exact minimizing value or interval.']);
 centers.forEach((c,j)=>{let curve;if(absolute){const knots=[r[0],...new Set(sorted),r[1]];curve=`<polyline points="${knots.map(u=>x(u)+','+y(loss(u))).join(' ')}" fill="none" stroke="#527f99" stroke-width="3"/>`;}else{const y0=y(loss(r[0])),controlY=y0-240*a.length*(r[0]-mean)*(r[1]-r[0])/maxLoss;curve=`<path d="M ${x(r[0])} ${y0} Q 500 ${controlY} ${x(r[1])} ${y(loss(r[1]))}" fill="none" stroke="#527f99" stroke-width="3"/>`;}let s=text(40,30,'Proposed center '+fmt(c)+'; total '+(absolute?'absolute':'squared')+' loss '+fmt(loss(c)))+axis(r,320,'Candidate center c')+vertical([0,maxLoss],'Total loss')+curve+dot(x(c),y(loss(c)),'center',null,'#ad6c38');if(absolute)s+=line(x(lo),320,x(hi),320,'#a06094')+text(500,425,`Minimizing interval: [${fmt(lo)}, ${fmt(hi)}]`,'math','middle');else s+=line(x(mean),80,x(mean),320,'#a06094','5 5')+text(500,425,'Mean = '+fmt(mean)+'; minimal loss = '+fmt(loss(mean)),'math','middle');frame(m,{values:a,center:c,contributions:a.map(v=>absolute?Math.abs(v-c):(v-c)**2),loss:loss(c),minimizer:absolute?[lo,hi]:mean},wrap(s,460),'Evaluate a center',absolute?'Every distance contributes its magnitude. Between the middle records, left and right slopes cancel.':'Centering at the mean removes the signed cross term; every other center adds a nonnegative quadratic penalty.',[[absolute?`${lo} ≤ ${fmt(c)} ≤ ${hi}`:`${fmt(c)} = ${fmt(mean)}`,absolute?c>=lo&&c<=hi:c===mean]],absolute?`loss = ${fmt(loss(c))}`:`loss = ${fmt(summary(a).m2)} + ${a.length} × (${fmt(c)} − ${fmt(mean)})²`,j<2?0:2);});m.result={mean,minimizer:absolute?[lo,hi]:mean,minimum:loss(absolute?(lo+hi)/2:mean)};return m;
}

function quantiles(a,id='quantiles'){
 const s=[...a].sort((a,b)=>a-b),m=make(id,'Quantiles: rank selection versus interpolation','quantile-conventions','Sorted slots remain fixed. Nearest rank selects one slot; type 7 joins two actual adjacent values using an explicit interpolation weight.',['Sort the observed values.','Calculate the nearest-rank position.','Calculate the type-7 position.','Separate the integer index from its fractional interpolation weight.']);const r=range(a),x=mapper(r,90,910);let answers=[];
 for(const p of [.25,.5,.75]){const rank=Math.max(1,Math.ceil(a.length*p)),h=1+(a.length-1)*p,j=Math.floor(h),g=h-j,nearest=s[rank-1],q=quant(a,p);for(const phase of ['nearest','type7']){let draw=text(40,32,`p = ${p}; ${phase==='nearest'?'nearest rank':'type-7 interpolation'}`)+axis(r,300,'Sorted observed value');s.forEach((v,k)=>{draw+=dot(x(v),120+(k%2)*40,'record-'+k,String(v),k===rank-1&&phase==='nearest'?'#ad6c38':'#497d99')+text(x(v),220+(k%2)*25,'rank '+(k+1),'math','middle');});const v=phase==='nearest'?nearest:q;draw+=dot(x(v),285,'quantile',null,'#a06094')+text(500,395,phase==='nearest'?`rank ceil(${a.length} × ${p}) = ${rank}; quantile = ${nearest}`:`position ${fmt(h)} = ${j} + ${fmt(g)}; quantile = ${fmt(q)}`,'math','middle');frame(m,{values:a,sorted:s,p,phase,rank,h,j,g,nearest,type7:q},wrap(draw,435),phase==='nearest'?'Select the ceiling rank':'Interpolate between adjacent ranks',phase==='nearest'?'The selected quantile is an observed value. The ceiling is applied to the rank, not to the value.':'The fractional part blends the surrounding sorted values; it is not the fraction of observations strictly below the answer.',[],phase==='nearest'?`Q = ${nearest}`:`Q = ${fmt(q)}`,phase==='nearest'?1:3);}answers.push({p,nearest,type7:q});}m.result=answers;return m;
}

function variance(a,id='variance'){
 const z=summary(a),r=range(a),x=mapper(r,90,910),m=make(id,'Variance: signed residuals, squared contributions and denominators','residual-energy','The number line and mean remain fixed. Signed residuals balance to zero; their squared contributions accumulate to a nonnegative centered sum.',['Fix the mean of the complete list.','Inspect one signed deviation.','Square that deviation and add its contribution.','Normalize the same centered sum by n or by n−1.']);let energy=0;
 const draw=i=>{let s=text(40,30,`Mean ${fmt(z.mean)}; inspected ${i}/${a.length}; accumulated M₂ = ${fmt(energy)}`)+axis(r,315,'Recorded value')+line(x(z.mean),75,x(z.mean),315,'#a06094','5 5');a.forEach((v,k)=>{const y=100+k*16;s+=line(x(v),y,x(z.mean),y,k<i?'#579187':'#cbd5db')+dot(x(v),y,'record-'+k,null,k<i?'#579187':'#cbd5db');});s+=text(40,418,'Final v = '+fmt(z.v)+'; corrected s² = '+fmt(z.s2),'math');return wrap(s,450);};
 frame(m,{values:a,mean:z.mean,inspected:0,energy},draw(0),'Fix the center','The mean uses the entire list. The running energy starts at zero.');a.forEach((v,i)=>{const d=v-z.mean;energy+=d*d;frame(m,{values:a,mean:z.mean,inspected:i+1,value:v,residual:d,square:d*d,energy},draw(i+1),'Add squared residual','Positive and negative deviations both contribute nonnegative energy; neither can cancel the other after squaring.',[[`${fmt(d*d)} ≥ 0`,true]],`M₂ = ${fmt(energy)}`,2);});m.result=z;frame(m,{...z,values:a},draw(a.length),'Choose the denominator','The centered sum is unchanged. Descriptive variance divides by the number of records; the corrected convention needs at least two.',[['n > 1',a.length>1]],`v = ${fmt(z.v)}; s² = ${fmt(z.s2)}`,3);return m;
}

function affine(a,scale,shift,id='affine'){
 const b=a.map(v=>scale*v+shift),old=summary(a),after=summary(b),r=range([...a,...b]),x=mapper(r,90,910),m=make(id,'Affine transformation: fixed units, moving record identities','affine-transform','Both before and after positions use one fixed value axis. Record identities remain attached; negative scaling reverses their order.',['Start with original observations.','Apply y = a x + b to each record.','Compare transformed center and spread.']);
 for(let j=0;j<=10;j++){const t=j/10,now=a.map((v,i)=>v+t*(b[i]-v));let s=text(40,30,`Transformation y = ${scale} x + ${shift}; progress ${j}/10`)+axis(r,320,'Common numerical axis');now.forEach((v,i)=>s+=dot(x(v),100+i*22,'record-'+i,'r'+i,'#497d99'));s+=text(40,425,`Final mean ${fmt(after.mean)}; final variance ${fmt(after.v)}; original variance ${fmt(old.v)}`,'math');frame(m,{values:a,transformed:b,positions:now,scale,shift,progress:t},wrap(s,455),j===0?'Initialize original positions':j===10?'Check the transformed summaries':'Move the same records','Intermediate positions visualize the affine mapping only; the final list is the statistically transformed data.',j===10?[[`new variance = ${scale*scale} × old variance`,Math.abs(after.v-scale*scale*old.v)<1e-8]]:[],`final mean = ${fmt(after.mean)}`,j===10?2:1);}m.result=after;return m;
}

function box(a,id='box'){
 const q1=quant(a,.25),med=quant(a,.5),q3=quant(a,.75),iqr=q3-q1,lower=q1-1.5*iqr,upper=q3+1.5*iqr,inside=a.filter(x=>x>=lower&&x<=upper),out=a.filter(x=>x<lower||x>upper),r=range([...a,lower,upper]),x=mapper(r,90,910),m=make(id,'Boxplot construction: quartiles, fences, observed whiskers','boxplot-construction','Type-7 quartiles define the box. Dashed fences are thresholds; solid whisker ends are actual retained observations. A fence-equal value is retained.',['Expose quartiles under type 7.','Compute IQR and the two fences.','Classify each record by strict fence comparisons.','Extend whiskers only to retained observed endpoints.']);
 for(let phase=0;phase<5;phase++){let s=text(40,30,'Type 7; strict 1.5-IQR rule; median '+fmt(med))+axis(r,320,'Observed numerical scale');a.forEach((v,i)=>s+=dot(x(v),90+(i%3)*22,'record-'+i,null,phase>=3&&out.includes(v)?'#b57047':'#789aab'));if(phase>=1)s+=`<rect x="${x(q1)}" y="185" width="${Math.max(.1,x(q3)-x(q1))}" height="60" fill="#dbe9e6" stroke="#5f8b87"/>`+line(x(med),185,x(med),245,'#805e96')+text(x(q1),165,'Q₁ '+fmt(q1),'math','middle')+text(x(q3),278,'Q₃ '+fmt(q3),'math','middle');if(phase>=2)s+=line(x(lower),70,x(lower),300,'#b57047','5 5')+line(x(upper),70,x(upper),300,'#b57047','5 5')+text(90,415,'Fences: '+fmt(lower)+' and '+fmt(upper),'math');if(phase>=4)s+=line(x(Math.min(...inside)),215,x(q1),215,'#557e8d')+line(x(q3),215,x(Math.max(...inside)),215,'#557e8d')+line(x(Math.min(...inside)),197,x(Math.min(...inside)),233,'#557e8d')+line(x(Math.max(...inside)),197,x(Math.max(...inside)),233,'#557e8d')+text(90,445,'Observed whiskers: '+fmt(Math.min(...inside))+' and '+fmt(Math.max(...inside))+'; outliers: '+(out.join(', ')||'none'),'math');frame(m,{values:a,q1,med,q3,iqr,lower,upper,retained:inside,outliers:out,phase},wrap(s,480),['Inspect the raw observations','Expose the central box','Calculate the fence thresholds','Classify outlier records','Attach observed whisker endpoints'][phase],['The observations are still the raw list; no fence or quartile has yet been displayed.','The box spans quartiles, and the median is a separate line inside it.','Fences can lie where no record exists. They are not whisker endpoints.','Only strict comparisons outside either fence mark an outlier; equality remains inside.','Solid horizontal whiskers stop at retained observations, while the dashed fence lines remain separate.'][phase],phase===3?a.map(v=>[`${v} < ${fmt(lower)} or ${v} > ${fmt(upper)}`,v<lower||v>upper]):[],`IQR = ${fmt(iqr)}`,Math.min(phase,3));}m.result={q1,median:med,q3,iqr,lower,upper,whiskers:[Math.min(...inside),Math.max(...inside)],outliers:out};return m;
}

function contamination(id='contamination'){
 const m=make(id,'One moving extreme: mean and variance respond, median stays at rank three','outlier-contamination','The scale remains fixed from 0 to 25. Only record r4 is replaced; the median stays at the third rank because the ordering is preserved.',['Replace only the maximum.','Recompute total and mean.','Keep the median rank fixed.','Recompute centered spread.']);const x=mapper([0,25],90,910);
 for(const M of [5,6,8,10,15,20,25]){const a=[1,2,3,4,M],z=summary(a);let s=text(40,30,'Replace 5 by '+M+'; median 3, mean '+fmt(z.mean))+axis([0,25],320,'Fixed value scale');a.forEach((v,i)=>s+=dot(x(v),105+i*20,'record-'+i,'r'+i,i===4?'#b57047':'#497d99'));s+=line(x(3),245,x(3),320,'#8f629f')+line(x(z.mean),270,x(z.mean),320,'#579187')+text(40,420,'Descriptive variance = '+fmt(z.v),'math');frame(m,{values:a,replacement:M,mean:z.mean,median:3,v:z.v},wrap(s,455),'Replace the extreme and recompute','The raw extreme moves outward. It changes total and residual energy but leaves the middle three-value ordering intact.',[[`M ≥ 5`,true]],`mean = (10 + ${M}) ÷ 5; median = 3`,2);}m.result=m.frames.at(-1).snapshot;return m;
}

function pooling(a,b,id='pooling'){
 const A=summary(a),B=summary(b),z=summary([...a,...b]),within=A.m2+B.m2,between=a.length*(A.mean-z.mean)**2+b.length*(B.mean-z.mean)**2,r=range([...a,...b]),x=mapper(r,90,910),m=make(id,'Group pooling: internal energy plus mean-gap energy','within-between-decomposition','The same observations are first centered within each group, then around the combined mean. The new between term cannot be recovered by averaging group variances.',['Compute each group summary.','Compute the size-weighted combined mean.','Separate within and between centered sums.','Add both and select the final denominator.']);
 for(let phase=0;phase<4;phase++){let s=text(40,30,'Group A mean '+fmt(A.mean)+'; group B mean '+fmt(B.mean))+axis(r,330,'Fixed observation scale');a.forEach((v,i)=>s+=dot(x(v),110+i*16,'A-'+i,null,'#5e9c90'));b.forEach((v,i)=>s+=dot(x(v),220+i*16,'B-'+i,null,'#8c73a2'));if(phase<2)s+=line(x(A.mean),70,x(A.mean),170,'#5e9c90','5 5')+line(x(B.mean),190,x(B.mean),290,'#8c73a2','5 5');else s+=line(x(z.mean),70,x(z.mean),305,'#b57047','5 5')+line(x(A.mean),165,x(z.mean),165,'#5e9c90')+line(x(B.mean),285,x(z.mean),285,'#8c73a2');s+=text(40,425,`Within M₂ ${fmt(within)}; between M₂ ${fmt(between)}; total M₂ ${fmt(z.m2)}`,'math');frame(m,{groupA:A,groupB:B,combined:z,within,between,phase,valuesA:a,valuesB:b},wrap(s,460),['Inspect separate group centers','Weight the two group totals','Expose the mean-gap contribution','Normalize the complete centered sum'][phase],phase<2?'Group means have record-count weights. Their internal centered sums describe only variation around separate centers.':'Recenter around the combined mean. The cross terms within each group vanish, leaving within energy plus the size-weighted squared mean gaps.',phase===3?[[`${fmt(within)} + ${fmt(between)} = ${fmt(z.m2)}`,Math.abs(within+between-z.m2)<1e-8]]:[],`combined mean = ${fmt(z.mean)}`,phase);}m.result={...z,within,between};return m;
}

function simpson(id='simpson'){
 const rows=[{name:'Easy',A:[9,10],B:[80,100]},{name:'Hard',A:[30,100],B:[2,10]},{name:'Overall',A:[39,110],B:[82,110]}],m=make(id,'Simpson reversal: rates and unequal exposure weights','mixture-rate-reversal','Each bar is a rate on the same 0–1 scale. Its displayed numerator and denominator expose the different task mixtures.',['Compare easy-task rates.','Compare hard-task rates.','Add successes and trials separately.','Compare aggregate rates and explain the mixture change.']);
 for(let phase=0;phase<4;phase++){let s=text(40,30,'Rate bars use the same width scale; labels retain actual trial counts');rows.slice(0,Math.min(3,phase+1)).forEach((r,j)=>{const y=95+j*120;s+=text(40,y+22,r.name);for(const [k,c] of [['A','#a5d3c6'],['B','#c7b9dc']]){const yy=y+(k==='B'?42:0),rate=r[k][0]/r[k][1];s+=`<rect x="220" y="${yy}" width="${rate*480}" height="28" fill="${c}"/>`+text(170,yy+21,k)+text(735,yy+21,`${r[k][0]}/${r[k][1]} = ${fmt(rate)}`,'math');}});const row=rows[Math.min(phase,2)];frame(m,{phase,rows:rows.slice(0,Math.min(3,phase+1))},wrap(s,480),phase<2?'Compare a task stratum':phase===2?'Compute aggregate rates':'Explain the reversed comparison',phase<2?'A has the larger success rate within this task class.':'A receives mostly hard tasks while B receives mostly easy tasks. The aggregates compare different mixture weights.',[[`A rate > B rate (${row.name})`,row.A[0]/row.A[1]>row.B[0]/row.B[1]]],'',Math.min(phase,3));}m.result={a:39/110,b:82/110};return m;
}

function stream(a,id='stream'){
 const m=make(id,'Welford updates: old residual, new center, updated energy','streaming-moments','The observation and mean use a fixed number line. The displayed delta uses the old mean; the second factor uses the updated mean.',['Start with an empty summary.','Read the next record and subtract the old mean.','Update the mean using the new count.','Update M₂ with delta times the new residual.']);let n=0,mean=0,m2=0;const r=range(a),x=mapper(r,90,910);
 const draw=(seen,v=null)=>{let s=text(40,30,`n = ${n}; mean = ${fmt(mean)}; M₂ = ${fmt(m2)}`)+axis(r,320,'Fixed incoming-value scale');a.slice(0,seen).forEach((v,i)=>s+=dot(x(v),100+i*17,'record-'+i,null));if(n)s+=dot(x(mean),260,'mean-marker','mean','#a06094');if(v!==null)s+=dot(x(v),225,'incoming','new x','#b57047');return wrap(s,420);};
 frame(m,{values:a,n,mean,m2},draw(0),'Initialize an empty stream','An empty mean is not a statistical estimate. Zero is an algorithmic initialization only; the first update produces the first actual mean.');a.forEach((v,i)=>{const oldMean=mean,delta=v-oldMean;frame(m,{values:a,n,mean,m2,incoming:v,delta},draw(i,v),'Compute the old-center residual','Subtract the previous summary mean before changing it. On the first record, the initialization will cancel correctly in the update.',[],`delta = ${fmt(v)} − ${fmt(oldMean)}`,1);n++;mean+=delta/n;frame(m,{values:a,n,mean,m2,incoming:v,oldMean,delta},draw(i,v),'Move the running mean','The same mean marker moves to the exact new center on fixed axes. M₂ has not yet been updated at this checkpoint.',[],`new mean = ${fmt(mean)}`,2);m2+=delta*(v-mean);frame(m,{values:a,n,mean,m2,incoming:v,delta,newResidual:v-mean},draw(i+1),'Accumulate centered energy','Multiply the old residual by the residual around the new mean. This accounts for recentering all previous records.',[[`M₂ ≥ 0`,m2>=-1e-9]],`M₂ = ${fmt(m2)}`,3);});m.result={n,mean,m2,v:m2/n,s2:n>1?m2/(n-1):null};return m;
}

function correlation(a,b,id='correlation'){
 if(a.length!==b.length)throw Error('Paired columns must have the same length.');const A=summary(a),B=summary(b),C=sum(a.map((v,i)=>(v-A.mean)*(b[i]-B.mean))),r=A.m2>0&&B.m2>0?C/Math.sqrt(A.m2*B.m2):null,rx=range(a),ry=range(b),x=mapper(rx,90,910),y=mapper(ry,320,80),m=make(id,'Paired scatter: accumulate signed cross-products','paired-covariance','Every plotted dot is one original pair. The two center lines remain fixed; quadrants determine the sign of its centered cross-product.',['Keep the original record pairing.','Center each coordinate separately.','Add the signed paired products.','Normalize only if both columns vary.']);let cross=0;
 const draw=i=>{let s=text(40,30,'Accumulated cross sum C = '+fmt(cross))+axis(rx,320,'X value')+vertical(ry,'Y value')+line(x(A.mean),80,x(A.mean),320,'#936da3','5 5')+line(90,y(B.mean),910,y(B.mean),'#936da3','5 5');for(let k=0;k<i;k++)s+=dot(x(a[k]),y(b[k]),'pair-'+k,'r'+k,(a[k]-A.mean)*(b[k]-B.mean)>=0?'#579187':'#b57047');s+=text(40,425,'Final r = '+fmt(r)+'; fixed Y range '+fmt(ry[0])+' to '+fmt(ry[1]),'math');return wrap(s,460);};
 frame(m,{x:a,y:b,meanX:A.mean,meanY:B.mean,inspected:0,cross},draw(0),'Fix both centers','Both means use the complete paired list. No pair has contributed yet.');a.forEach((v,i)=>{const product=(v-A.mean)*(b[i]-B.mean);cross+=product;frame(m,{x:a,y:b,meanX:A.mean,meanY:B.mean,inspected:i+1,product,cross},draw(i+1),'Add one paired cross-product','Same-sign centered deviations contribute positively; opposite signs contribute negatively. The original pairing is preserved.',[[`paired product ≥ 0`,product>=0]],`C = ${fmt(cross)}`,2);});m.result={covariance:C/a.length,r,cross:C,m2x:A.m2,m2y:B.m2};frame(m,{...m.result,x:a,y:b},draw(a.length),'Check the normalization contract',r===null?'At least one column is constant. Covariance can be zero while normalized correlation is undefined.':'Both centered sums are positive, so Pearson normalization is defined. Zero describes linear cancellation only.',[['both centered sums > 0',r!==null]],`r = ${fmt(r)}`,3);return m;
}

function qq(a,b,id='qq'){
 const s=[...a].sort((a,b)=>a-b),t=[...b].sort((a,b)=>a-b),rx=range(a),ry=range(b),x=mapper(rx,90,910),y=mapper(ry,320,80),m=make(id,'Two-sample Q–Q: compare equal probability levels','quantile-comparison','These dots pair distribution quantiles, not original subjects. Type-7 interpolation aligns probabilities even when the sample sizes differ.',['Sort each sample independently.','Choose a common probability level.','Interpolate each sample at that level.','Place the corresponding quantile pair.']);let pairs=[];
 for(const p of [0,.125,.25,.5,.75,.875,1]){const u=quant(s,p),v=quant(t,p);pairs.push({p,x:u,y:v});let svg=text(40,30,'Type-7 paired quantiles; newest probability '+p)+axis(rx,320,'Sample A quantile')+vertical(ry,'Y value');pairs.forEach((q,i)=>svg+=dot(x(q.x),y(q.y),'quantile-'+i,null));svg+=text(40,420,`Q_A = ${fmt(u)}, Q_B = ${fmt(v)}; Y range ${fmt(ry[0])} to ${fmt(ry[1])}`,'math');frame(m,{sampleA:s,sampleB:t,p,pairs},wrap(svg,455),'Plot a common-probability pair','The probability level, rather than original record identity, establishes this pair. Distributional shape comparison does not recover subject-level association.',[],`p = ${p}`,2);}m.result=pairs;return m;
}

function smoothing(a,parameter,ewma=false,id='smoothing'){
 const m=make(id,ewma?'EWMA: retain initialization and update after observing':'Trailing moving average: window enters and leaves','time-series-smoothing','Time order remains fixed. The newest computed summary includes the current observation; a one-step forecast uses the previous summary.',['Observe the next time point.','Select the available trailing window or previous EWMA.','Compute the new summary with its actual denominator or weight.','Use the previous summary for a next-step forecast.']);let sm=[],old=0;const rx=[0,a.length+1],ry=range([...a,0]),x=mapper(rx,90,910),y=mapper(ry,320,80);
 for(let i=0;i<a.length;i++){const start=ewma?0:Math.max(0,i-parameter+1),window=a.slice(start,i+1),value=ewma?parameter*a[i]+(1-parameter)*old:sum(window)/window.length,forecast=i?sm.at(-1):null;sm.push(value);let s=text(40,30,ewma?`lambda = ${parameter}; E₀ = 0; current time ${i+1}`:`trailing width ${parameter}; shorter-window startup; time ${i+1}`)+axis(rx,320,'Time index')+vertical(ry,'Series value');if(!ewma)s+=`<rect x="${x(start+1)-15}" y="75" width="${x(i+1)-x(start+1)+30}" height="250" fill="#e6eee6" opacity=".55"/>`;a.slice(0,i+1).forEach((v,k)=>{if(k)s+=line(x(k),y(a[k-1]),x(k+1),y(v),'#8095a3');s+=dot(x(k+1),y(v),'raw-'+k,null,'#8095a3');});sm.forEach((v,k)=>{if(k)s+=line(x(k),y(sm[k-1]),x(k+1),y(v),'#8c669e');s+=dot(x(k+1),y(v),'smooth-'+k,null,'#8c669e');});s+=text(40,425,`New summary ${fmt(value)}; previous forecast ${fmt(forecast)}; raw ${a[i]}`,'math');frame(m,{values:a,time:i+1,window:ewma?null:window,parameter,previous:old,summary:value,forecast,summaries:sm},wrap(s,460),'Observe, then update',ewma?'The newest value receives lambda weight and the previous state retains the rest. Initialization is part of that previous state.':'The highlighted window contains only current and past values. Startup divides by its actual current length.',[[ewma?'0 < lambda ≤ 1':'window length ≤ requested width',ewma?parameter>0&&parameter<=1:window.length<=parameter]],`summary = ${fmt(value)}`,2);old=value;}m.result=sm;return m;
}

function fixtures(){const groups={},models=[];const add=(group,m)=>{(groups[group]??=[]).push(m.id);models.push(m);};
 add('histogram',histogram([0,1,1,2,3,4],[0,1,2,4],'hist-edges'));add('histogram',histogram([.2,.4,.6,.8,1.2,1.8,2.2,2.8],[0,1,3],'hist-equal'));
 add('ecdf',ecdf([1,2,2,5],'ecdf-ties'));
 add('mean',center([1,3,8,10],'mean-loss'));
 add('quantiles',quantiles([1,5,8,15],'quant-four'));add('quantiles',quantiles([1,1,1,2,5,5,8,9],'quant-ties'));
 add('loss',center([1,3,8,10],'loss-gap',true));add('loss',center([0,0,0,10,20],'loss-robust',true));
 add('variance',variance([1,2,2,3,4,6],'variance-basic'));add('variance',variance([0,2,4],'variance-three'));add('variance',variance([5],'variance-single'));
 add('affine',affine([1,2,3,4,5],-3,7,'affine-negative'));add('affine',affine([1,2,3,4,5],1,10,'affine-shift'));
 add('box',box([1,2,3,4,5,6,7,20],'box-example'));add('box',box([0,0,0,0,0,0,0,100],'box-zero'));add('box',contamination('outlier-motion'));
 add('pooling',pooling([0,0],[6,6],'pool-constant'));add('pooling',pooling([1,2,3],[6,8],'pool-nonconstant'));add('pooling',simpson('simpson-example'));
 add('stream',stream([0,2,4,10],'stream-example'));add('stream',stream([10,10,10],'stream-constant'));
 add('correlation',correlation([-1,0,1],[1,0,1],'correlation-curve'));add('correlation',correlation([1,2,3],[2,1,4],'correlation-pairs'));add('correlation',correlation([2,2,2],[1,3,8],'correlation-constant'));
 add('qq',qq([0,1,2,4],[5,7,9,13],'qq-affine'));add('qq',qq([0,1,2],[0,0,1,2,8],'qq-different-sizes'));
 add('smoothing',smoothing([2,4,10,8],3,false,'smoothing-ma'));add('smoothing',smoothing([2,4,10],.5,true,'smoothing-ewma'));
 return {topicId:'s_descriptive',groups,models};}
const api={summary,quant,histogram,ecdf,center,quantiles,variance,affine,box,contamination,pooling,simpson,stream,correlation,qq,smoothing,fixtures};
if(typeof module!=='undefined'){module.exports=api;return;}globalThis.StatisticsModels=api;
const controls=()=>'<div class="stat-controls"><button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed><option value="2600">Slow</option><option value="1800" selected>Normal</option><option value="1300">Fast</option></select></label><label>Step<input type="range" data-seek min="0" value="0"></label></div><div class="stat-stage"></div><p class="stat-caption"></p><p data-progress></p><div class="stat-formula formula-block"></div><div class="stat-print"></div>';
function mount(host,m){return AdvancedSimulations.mount(host,m,{topic:"s_descriptive",prefix:"stat"});}
async function boot(){const data=await(await fetch('s_descriptive-models.json')).json();globalThis.StatisticsPlayers=[];for(const h of document.querySelectorAll('[data-stat-model]')){const m=data.models.find(m=>m.id===h.dataset.statModel);if(!m)throw Error('Missing statistics model '+h.dataset.statModel);StatisticsPlayers.push(mount(h,m));}const form=document.querySelector('#stat-form'),output=document.querySelector('#stat-output'),error=document.querySelector('#stat-error');let current=null;
 const numbers=s=>{const parts=String(s).split(',').map(x=>x.trim());if(!parts.length||parts.some(x=>!/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(x)))throw Error('Use comma-separated finite numbers with no empty fields.');const a=parts.map(Number);if(a.length>12||a.some(x=>!Number.isFinite(x)||Math.abs(x)>999))throw Error('Use 1–12 values from −999 to 999.');return a;};
 form.addEventListener('submit',e=>{e.preventDefault();try{const fd=new FormData(form),kind=fd.get('kind'),a=numbers(fd.get('values')),parameter=Number(fd.get('parameter'));let m;
 if(kind==='histogram'){const edges=numbers(fd.get('other'));if(edges.length<2||edges.some((x,i)=>i&&x<=edges[i-1]))throw Error('Supply at least two strictly increasing bin edges.');m=histogram(a,edges,'editable');}
 else if(kind==='ecdf')m=ecdf(a,'editable');else if(kind==='mean')m=center(a,'editable');else if(kind==='median')m=center(a,'editable',true);else if(kind==='quantiles')m=quantiles(a,'editable');else if(kind==='variance')m=variance(a,'editable');else if(kind==='box')m=box(a,'editable');else if(kind==='stream')m=stream(a,'editable');
 else if(kind==='affine'){if(!Number.isFinite(parameter)||Math.abs(parameter)>20)throw Error('Use a finite scale from −20 to 20.');const shift=numbers(fd.get('other'));if(shift.length!==1)throw Error('Affine mode needs one translation value in the second field.');m=affine(a,parameter,shift[0],'editable');}
 else if(kind==='pooling')m=pooling(a,numbers(fd.get('other')),'editable');else if(kind==='correlation')m=correlation(a,numbers(fd.get('other')),'editable');else if(kind==='qq')m=qq(a,numbers(fd.get('other')),'editable');else if(kind==='ma'){if(!Number.isInteger(parameter)||parameter<1||parameter>12)throw Error('Moving-average width must be an integer from 1 to 12.');m=smoothing(a,parameter,false,'editable');}else if(kind==='ewma'){if(!Number.isFinite(parameter)||parameter<=0||parameter>1)throw Error('EWMA lambda must be greater than zero and at most one.');m=smoothing(a,parameter,true,'editable');}else throw Error('Choose a valid mode.');
 current?.dispose();output.innerHTML='<section class="stat-model" tabindex="0"><h3>'+esc(m.title)+'</h3><p>'+esc(m.invariant)+'</p>'+controls()+'</section>';current=mount(output.firstChild,m);globalThis.StatisticsLab=current;error.textContent='';}catch(err){error.textContent=err.message;}});
}
boot().catch(err=>{console.error(err);document.querySelector('#stat-error').textContent='The models could not load. Reload the chapter to retry.';});
})();
